import * as React from "react"
import { ChevronLeft, ChevronRight, ChevronDown } from "lucide-react"
import { 
  format, 
  addMonths, 
  subMonths, 
  startOfMonth, 
  endOfMonth, 
  startOfWeek, 
  endOfWeek, 
  isSameMonth, 
  isSameDay, 
  eachDayOfInterval,
  isToday
} from "date-fns"
import { es } from "date-fns/locale"
import { useLanguage } from "../../context/LanguageContext"
import { cn } from "../../lib/utils"

export interface CalendarProps {
  selected?: Date
  onSelect?: (date: Date) => void
  className?: string
}

export function Calendar({ selected, onSelect, className }: CalendarProps) {
  const { language } = useLanguage()
  const [currentMonth, setCurrentMonth] = React.useState(selected || new Date())
  const [showMonthDropdown, setShowMonthDropdown] = React.useState(false)
  const [showYearDropdown, setShowYearDropdown] = React.useState(false)
  const containerRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    if (selected) {
      setCurrentMonth(selected)
    }
  }, [selected])

  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setShowMonthDropdown(false);
        setShowYearDropdown(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const nextMonth = () => setCurrentMonth(addMonths(currentMonth, 1))
  const prevMonth = () => setCurrentMonth(subMonths(currentMonth, 1))

  const monthStart = startOfMonth(currentMonth)
  const monthEnd = endOfMonth(monthStart)
  const startDate = startOfWeek(monthStart)
  const endDate = endOfWeek(monthEnd)

  const calendarDays = eachDayOfInterval({
    start: startDate,
    end: endDate,
  })

  const rows: Date[][] = []
  let days: Date[] = []

  calendarDays.forEach((day, i) => {
    days.push(day)
    if ((i + 1) % 7 === 0) {
      rows.push(days)
      days = []
    }
  })

  const handleSelectToday = () => {
    const today = new Date();
    setCurrentMonth(today);
    onSelect?.(today);
  };

  const handleSelectYesterday = () => {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    setCurrentMonth(yesterday);
    onSelect?.(yesterday);
  };

  return (
    <div ref={containerRef} className={cn("p-1.5 bg-transparent select-none relative w-full", className)}>
      {/* Quick Date Presets */}
      <div className="flex items-center justify-center gap-1.5 mb-2.5">
        <button
          type="button"
          onClick={handleSelectToday}
          className="px-3 py-1 rounded-full text-[11px] font-medium bg-muted/60 hover:bg-muted text-muted-foreground hover:text-foreground transition-all cursor-pointer border border-border/40 hover:border-border/70"
        >
          {language === 'es' ? 'Hoy' : 'Today'}
        </button>
        <button
          type="button"
          onClick={handleSelectYesterday}
          className="px-3 py-1 rounded-full text-[11px] font-medium bg-muted/60 hover:bg-muted text-muted-foreground hover:text-foreground transition-all cursor-pointer border border-border/40 hover:border-border/70"
        >
          {language === 'es' ? 'Ayer' : 'Yesterday'}
        </button>
      </div>

      {/* Month & Year Navigation Header */}
      <div className="flex items-center justify-between mb-2 px-1">
        <div className="flex items-center gap-1.5">
          {/* Custom Month Select */}
          <div className="relative">
            <button
              type="button"
              onClick={() => {
                setShowMonthDropdown(!showMonthDropdown);
                setShowYearDropdown(false);
              }}
              className="h-7 px-2.5 rounded-lg border border-border/50 bg-background/80 hover:bg-muted/60 text-xs font-medium text-foreground flex items-center gap-1 transition-all cursor-pointer"
            >
              <span className="capitalize">{format(currentMonth, "MMMM", { locale: language === 'es' ? es : undefined })}</span>
              <ChevronDown size={12} className="text-muted-foreground/80 shrink-0" />
            </button>
            {showMonthDropdown && (
              <div className="absolute top-full left-0 mt-1 w-32 max-h-48 overflow-y-auto bg-card/98 border border-border/80 rounded-xl shadow-xl z-50 py-1 backdrop-blur-xl flex flex-col gap-0.5 custom-scrollbar">
                {Array.from({ length: 12 }, (_, i) => {
                  const date = new Date(2024, i, 1);
                  const name = format(date, "MMMM", { locale: language === 'es' ? es : undefined });
                  return (
                    <button
                      key={i}
                      type="button"
                      onClick={() => {
                        const next = new Date(currentMonth);
                        next.setMonth(i);
                        setCurrentMonth(next);
                        setShowMonthDropdown(false);
                      }}
                      className={cn(
                        "w-full text-left px-3 py-1.5 text-xs transition-colors cursor-pointer capitalize",
                        currentMonth.getMonth() === i 
                          ? "text-primary bg-primary/10 font-medium" 
                          : "text-foreground/80 hover:bg-muted/70 hover:text-foreground font-normal"
                      )}
                    >
                      {name}
                    </button>
                  );
                })}
              </div>
            )}
          </div>

          {/* Custom Year Select */}
          <div className="relative">
            <button
              type="button"
              onClick={() => {
                setShowYearDropdown(!showYearDropdown);
                setShowMonthDropdown(false);
              }}
              className="h-7 px-2.5 rounded-lg border border-border/50 bg-background/80 hover:bg-muted/60 text-xs font-medium text-foreground flex items-center gap-1 transition-all cursor-pointer"
            >
              <span>{format(currentMonth, "yyyy")}</span>
              <ChevronDown size={12} className="text-muted-foreground/80 shrink-0" />
            </button>
            {showYearDropdown && (
              <div className="absolute top-full left-0 mt-1 w-24 max-h-48 overflow-y-auto bg-card/98 border border-border/80 rounded-xl shadow-xl z-50 py-1 backdrop-blur-xl flex flex-col gap-0.5 custom-scrollbar">
                {Array.from({ length: 120 }, (_, i) => {
                  const year = new Date().getFullYear() - i;
                  return (
                    <button
                      key={year}
                      type="button"
                      onClick={() => {
                        const next = new Date(currentMonth);
                        next.setFullYear(year);
                        setCurrentMonth(next);
                        setShowYearDropdown(false);
                      }}
                      className={cn(
                        "w-full text-left px-3 py-1.5 text-xs transition-colors cursor-pointer",
                        currentMonth.getFullYear() === year 
                          ? "text-primary bg-primary/10 font-medium" 
                          : "text-foreground/80 hover:bg-muted/70 hover:text-foreground font-normal"
                      )}
                    >
                      {year}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Prev / Next Month arrows */}
        <div className="flex items-center gap-0.5">
          <button
            type="button"
            onClick={prevMonth}
            className="size-7 rounded-lg flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/70 transition-colors cursor-pointer"
            title="Previous month"
          >
            <ChevronLeft size={15} />
          </button>
          <button
            type="button"
            onClick={nextMonth}
            className="size-7 rounded-lg flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/70 transition-colors cursor-pointer"
            title="Next month"
          >
            <ChevronRight size={15} />
          </button>
        </div>
      </div>

      {/* Days of Week Header */}
      <div className="grid grid-cols-7 mb-1">
        {(language === 'es' ? ["Do", "Lu", "Ma", "Mi", "Ju", "Vi", "Sa"] : ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"]).map((day) => (
          <div key={day} className="text-center text-[10px] font-medium text-muted-foreground/60 py-0.5">
            {day}
          </div>
        ))}
      </div>

      {/* Days Grid */}
      <div className="space-y-0.5">
        {rows.map((row, i) => (
          <div key={i} className="grid grid-cols-7 gap-0.5">
            {row.map((day) => {
              const isSelected = selected && isSameDay(day, selected)
              const isCurrentMonth = isSameMonth(day, monthStart)
              const isTodayDay = isToday(day)

              return (
                <button
                  type="button"
                  key={day.toString()}
                  onClick={() => onSelect?.(day)}
                  className={cn(
                    "size-7.5 mx-auto text-xs rounded-full transition-all relative flex items-center justify-center cursor-pointer",
                    !isCurrentMonth && "text-muted-foreground/20 pointer-events-none",
                    isCurrentMonth && !isSelected && "text-foreground/80 font-normal hover:bg-muted/80 hover:text-foreground",
                    isSelected && "bg-primary text-primary-foreground font-medium shadow-xs",
                    isTodayDay && !isSelected && "text-primary font-medium ring-1 ring-primary/40"
                  )}
                >
                  {format(day, "d")}
                  {isTodayDay && !isSelected && (
                    <div className="absolute bottom-0.5 size-0.5 rounded-full bg-primary" />
                  )}
                </button>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}
